{
  "name": "HDAWG高密度任意波形发生器",
  "name_en": "HDAWG High-Density Arbitrary Waveform Generator",
  "manufacturer": "Zurich Instruments",
  "description": "这是一种高密度多通道任意波形发生器，可输出高速可编程波形，并通过触发、外部时钟和数字I/O与其他实验设备同步。它常用于量子控制实验、脉冲序列生成、时序联动和精密电子测量。",
  "description_en": "This is a high-density multi-channel arbitrary waveform generator that produces high-speed programmable waveforms and synchronizes with other lab instruments through triggers, external clocks, and digital I/O. It is commonly used for quantum control experiments, pulse-sequence generation, timing coordination, and precision electronic measurements.",
  "tag_hints": [
    "arbitrary waveform generation",
    "multi-channel AWG",
    "digital I/O synchronization",
    "external clock reference",
    "quantum control pulses",
    "triggered waveform output"
  ],
  "actions": [
    {
      "action_name": "auto-awg_dio_snapshot",
      "description": "读取指定AWG相关数字I/O位的快照。",
      "description_en": "Capture a snapshot of digital I/O bits associated with a specified AWG."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准AWG的数字I/O通信协议。",
      "description_en": "Calibrate the digital I/O protocol for the AWGs."
    },
    {
      "action_name": "auto-configure_awg_file",
      "description": "从文件加载并配置AWG波形程序。",
      "description_en": "Load and configure an AWG waveform program from a file."
    },
    {
      "action_name": "auto-configure_awg_string",
      "description": "用字符串内容配置AWG波形程序。",
      "description_en": "Configure an AWG waveform program from a string."
    },
    {
      "action_name": "auto-connect_device",
      "description": "连接指定设备并初始化相关模块。",
      "description_en": "Connect to the specified device and initialize related modules."
    },
    {
      "action_name": "auto-dio_snapshot",
      "description": "读取数字I/O位状态快照。",
      "description_en": "Capture a snapshot of digital I/O bit states."
    },
    {
      "action_name": "auto-dio_testmode",
      "description": "设置数字I/O测试模式。",
      "description_en": "Set the digital I/O test mode."
    },
    {
      "action_name": "auto-direct",
      "description": "设置所选输出通道是否使用直接输出模式。",
      "description_en": "Set whether the selected outputs use direct output mode."
    },
    {
      "action_name": "auto-extclk",
      "description": "设置是否使用外部时钟参考。",
      "description_en": "Set whether to use an external clock reference."
    },
    {
      "action_name": "auto-mode",
      "description": "设置所选输出通道的输出模式或幅度相关配置。",
      "description_en": "Set the output mode or amplitude-related configuration for the selected outputs."
    },
    {
      "action_name": "auto-off",
      "description": "关闭指定输出通道。",
      "description_en": "Turn off the specified output channels."
    },
    {
      "action_name": "auto-on",
      "description": "开启指定输出通道。",
      "description_en": "Turn on the specified output channels."
    },
    {
      "action_name": "auto-sampleclk",
      "description": "设置采样时钟速率。",
      "description_en": "Set the sample clock rate."
    },
    {
      "action_name": "auto-idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-set_trigger_mode",
      "description": "设置触发模式。",
      "description_en": "Set the trigger mode."
    },
    {
      "action_name": "auto-set_trigger_level",
      "description": "设置触发电平。",
      "description_en": "Set the trigger level."
    },
    {
      "action_name": "auto-set_trigger_ext",
      "description": "设置外部触发相关配置。",
      "description_en": "Set the external trigger configuration."
    },
    {
      "action_name": "auto-set_trigger_src",
      "description": "设置触发源。",
      "description_en": "Set the trigger source."
    },
    {
      "action_name": "auto-set_trigger_slope",
      "description": "设置触发边沿斜率。",
      "description_en": "Set the trigger edge slope."
    },
    {
      "action_name": "auto-set_trigger_coupling",
      "description": "设置触发耦合方式。",
      "description_en": "Set the trigger coupling."
    },
    {
      "action_name": "auto-set_time_scale",
      "description": "设置时间基准刻度。",
      "description_en": "Set the time scale."
    },
    {
      "action_name": "auto-set_channel_scale",
      "description": "设置通道幅度刻度。",
      "description_en": "Set the channel scale."
    },
    {
      "action_name": "auto-do_single_shot",
      "description": "执行一次单次采集。",
      "description_en": "Perform a single-shot acquisition."
    },
    {
      "action_name": "auto-set_averaging",
      "description": "设置是否启用平均采集。",
      "description_en": "Set whether averaging is enabled."
    },
    {
      "action_name": "auto-set_format_real",
      "description": "设置实数格式数据输出。",
      "description_en": "Set real-format data output."
    },
    {
      "action_name": "auto-set_average_count",
      "description": "设置平均次数。",
      "description_en": "Set the averaging count."
    },
    {
      "action_name": "auto-sync",
      "description": "同步设备状态与控制系统设置。",
      "description_en": "Synchronize device state with the control system settings."
    },
    {
      "action_name": "auto-do_get_screenshot",
      "description": "获取当前显示界面的截图。",
      "description_en": "Capture a screenshot of the current display."
    },
    {
      "action_name": "auto-get_channel_data",
      "description": "读取通道波形数据。",
      "description_en": "Read waveform data from a channel."
    },
    {
      "action_name": "auto-is_averaging_complete",
      "description": "获取平均采集是否完成。",
      "description_en": "Get whether averaging acquisition is complete."
    },
    {
      "action_name": "auto-set_maximum_rate",
      "description": "设置最大数据速率。",
      "description_en": "Set the maximum data rate."
    },
    {
      "action_name": "auto-connect_server",
      "description": "连接设备控制或数据服务器。",
      "description_en": "Connect to the device control or data server."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接设备或控制服务器。",
      "description_en": "Reconnect to the device or control server."
    },
    {
      "action_name": "auto-load_settings",
      "description": "加载已保存的设备设置。",
      "description_en": "Load saved device settings."
    },
    {
      "action_name": "auto-features",
      "description": "查询设备支持的功能特性。",
      "description_en": "Query the device's supported features."
    },
    {
      "action_name": "auto-setd",
      "description": "设置双精度参数值。",
      "description_en": "Set a double-precision parameter value."
    },
    {
      "action_name": "auto-seti",
      "description": "设置整数参数值。",
      "description_en": "Set an integer parameter value."
    },
    {
      "action_name": "auto-setv",
      "description": "设置向量参数值。",
      "description_en": "Set a vector parameter value."
    },
    {
      "action_name": "auto-geti",
      "description": "获取整数参数值。",
      "description_en": "Get an integer parameter value."
    },
    {
      "action_name": "auto-getd",
      "description": "获取双精度参数值。",
      "description_en": "Get a double-precision parameter value."
    },
    {
      "action_name": "auto-getv",
      "description": "获取向量参数值。",
      "description_en": "Get a vector parameter value."
    },
    {
      "action_name": "auto-find",
      "description": "查找匹配的参数或节点。",
      "description_en": "Find a matching parameter or node."
    },
    {
      "action_name": "auto-finds",
      "description": "查找多个匹配的参数或节点。",
      "description_en": "Find multiple matching parameters or nodes."
    },
    {
      "action_name": "auto-subs",
      "description": "订阅设备数据节点。",
      "description_en": "Subscribe to device data nodes."
    },
    {
      "action_name": "auto-unsubs",
      "description": "取消订阅设备数据节点。",
      "description_en": "Unsubscribe from device data nodes."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询已订阅的数据。",
      "description_en": "Poll subscribed data."
    },
    {
      "action_name": "auto-read_scope",
      "description": "读取示波采集数据。",
      "description_en": "Read scope acquisition data."
    },
    {
      "action_name": "auto-restart",
      "description": "重启设备或相关采集模块。",
      "description_en": "Restart the device or related acquisition modules."
    },
    {
      "action_name": "auto-onOffMultiple",
      "description": "同时开启或关闭多个输出通道。",
      "description_en": "Turn multiple output channels on or off simultaneously."
    }
  ]
}

